from pathlib import Path
import re,json,hashlib
root=Path.cwd(); out=root/'documentation'
for d in ['chapters','figures','extraits','verification']: (out/d).mkdir(parents=True,exist_ok=True)
def esc(t):
 return ''.join({'\\':r'\textbackslash{}','&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}'}.get(c,c) for c in t)
def write(p,t): (out/p).write_text(t.rstrip()+'\n',encoding='utf-8')
def para(t):return esc(t)+'\n\n'
def section(title,t):return '\\section{'+esc(title)+'}\n'+para(t)
manifest=[]
def excerpt(path,start,count,name):
 lines=(root/path).read_text(encoding='utf-8-sig').splitlines(); selected=lines[start-1:start-1+count]; dest=f'extraits/{name}.txt'; write(dest,'\n'.join(selected)+'\n')
 manifest.append({'source':path,'firstLine':start,'lastLine':start+len(selected)-1,'excerpt':dest,'sha256':hashlib.sha256((root/path).read_bytes()).hexdigest()})
 return '\\paragraph{Code observé} '+esc(path)+f' (lignes {start} à {start+len(selected)-1}).\n\\lstinputlisting{{{dest}}}\n'
